def enrich_texts(texts):
    for index, text in enumerate(texts):
        if text["slug"] == "floresta-amazonica":
            for language, anchor in (("pt", "Para quem visita a região"), ("fr", "Pour les visiteurs")):
                key = "texto_" + language
                first = text[key].find(anchor)
                repeated = text[key].find(anchor, first + 1)
                if first >= 0 and repeated >= 0:
                    text[key] = text[key][:repeated].rstrip()
        extra = EXTRAS.get(text["slug"])
        if extra:
            text["texto_pt"] += extra["pt"]
            text["texto_fr"] += extra["fr"]
            for question_pt, question_fr, options_pt, options_fr, answer in extra["quiz"]:
                text["quiz"].append({
                    "pergunta_pt": question_pt,
                    "pergunta_fr": question_fr,
                    "opcoes_pt": options_pt,
                    "opcoes_fr": options_fr,
                    "resposta": answer,
                })
        vocab = text.get("vocabulario", [])
        if len(vocab) >= 4:
            options = [item["fr"] for item in vocab[:4]]
            answer = index % 4
            options[0], options[answer] = options[answer], options[0]
            text["quiz"].append({
                "pergunta_pt": f'Qual é a tradução de “{vocab[0]["pt"]}” em francês?',
                "pergunta_fr": f'Que signifie « {vocab[0]["pt"]} » en français ?',
                "opcoes_pt": options,
                "opcoes_fr": options,
                "resposta": answer,
            })
